    interview: { q: "Why does INT4 weight quantization speed up decoding more than prefill?", level: 4, outline: ["decode is bandwidth-bound: bytes per weight dominate", "prefill is compute-bound: arithmetic dominates", "fewer bytes helps decode nearly proportionally", "dequantization overhead matters more in prefill"] },
